unsafe extern "C" fn find_cipher(
    mut ctx_0: *mut ptls_context_t,
    mut id: uint16_t,
) -> *const ptls_cipher_suite_t {
    let mut cs: *mut *const ptls_cipher_suite_t =
        ::core::ptr::null_mut::<*const ptls_cipher_suite_t>();
    cs = (*ctx_0).cipher_suites;
    while !(*cs).is_null() {
        if (**cs).id as ::core::ffi::c_int == id as ::core::ffi::c_int {
            return *cs;
        }
        cs = cs.offset(1);
    }
    return ::core::ptr::null::<ptls_cipher_suite_t>();
}
